// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    Log lg;

    function setUp() public {
        lg = new Log();
        c = new MY_BANK(address(lg));
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(c));
        amount = bound(amount, 0, 1e30);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);

        bool ok = false;
        try lg.History(0) returns (address sender, string memory, uint256 val, uint256) {
            ok = (sender == actor && val == amount);
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}
